import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"为 Open Cube OS 做贡献","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/CONTRIBUTING.md","filePath":"zh/root/CONTRIBUTING.md"}'),i={name:"zh/root/CONTRIBUTING.md"};function l(d,e,n,c,r,p){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="为-open-cube-os-做贡献" tabindex="-1">为 Open Cube OS 做贡献 <a class="header-anchor" href="#为-open-cube-os-做贡献" aria-label="Permalink to &quot;为 Open Cube OS 做贡献&quot;">​</a></h1><p>感谢您对做出贡献的兴趣！Open Cube OS 是一个从零开始的 x86_64 内核，每一份贡献——代码、文档、驱动点亮、错误报告——都受到欢迎。</p><h2 id="基本规则" tabindex="-1">基本规则 <a class="header-anchor" href="#基本规则" aria-label="Permalink to &quot;基本规则&quot;">​</a></h2><ol><li><p><strong>内核字符串必须是 ASCII 英文。</strong> 系统自身打印的所有内容（命令名、提示符、启动消息、帮助文本）必须保持纯 ASCII。非 ASCII 文本可以出现在用户数据和文档中，绝不能出现在内核可见的字符串中。</p></li><li><p><strong>命令接口面只增不减。</strong> 已经发布的 Shell 命令可以在内部进行重构，但其名称和整体行为必须保持不变；删除会破坏接口契约。使用 <code>shell_register_command_ex()</code> 和工作包标签来注册新命令。</p></li><li><p><strong>零警告。</strong> 构建时使用 <code>-Wall -Wextra -Werror</code> 编译。引入警告的变更就是破坏性的变更，无论是在您的机器上还是在 CI 上。</p></li><li><p><strong>无存根，无假数据。</strong> 如果一个功能是部分的，请在代码和文档中明确说明——绝不要掩盖它。一个仅探测并报告&quot;在此机器上不支持&quot;的驱动是可以的；一个假装工作的驱动则不行。</p></li><li><p><strong>全面使用 Apache 2.0。</strong> 每个新的源文件都以 SPDX 头部开始：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* SPDX-License-Identifier: Apache-2.0 */</span></span>
<span class="line"><span>/* Copyright 2026 cubestudio-dev &lt;cubestudio@qq.com&gt; */</span></span></code></pre></div></li></ol><h2 id="开发流程" tabindex="-1">开发流程 <a class="header-anchor" href="#开发流程" aria-label="Permalink to &quot;开发流程&quot;">​</a></h2><h3 id="_1-开始构建" tabindex="-1">1. 开始构建 <a class="header-anchor" href="#_1-开始构建" aria-label="Permalink to &quot;1. 开始构建&quot;">​</a></h3><p>遵循 <a href="./BUILDING.html">BUILDING.md</a>。在 Linux 上的简短版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./build.sh iso          # kernel + bootable ISO</span></span>
<span class="line"><span>make test               # host-side unit tests</span></span></code></pre></div><p>您需要 <code>gcc, nasm, grub-mkimage, xorriso, mtools, python3, zip</code> （<code>tools/build.sh</code> 会检查并告诉您具体缺少哪些，或使用 <code>--install</code> 安装它们）。</p><h3 id="_2-进行您的修改" tabindex="-1">2. 进行您的修改 <a class="header-anchor" href="#_2-进行您的修改" aria-label="Permalink to &quot;2. 进行您的修改&quot;">​</a></h3><ul><li>保持修改的专注性：每个拉取请求只包含一个驱动、一个修复、一个文档章节。</li><li>每个内核源文件都带有 SPDX 头部——请保留它。</li><li>新命令：在相应的 <code>shell/shell_cmds_*.c</code> 中注册，添加帮助行，并扩展回归预期（见 <code>tools/run_fix4_regression.py</code>，命令计数基线）。</li></ul><h3 id="_3-推送前测试" tabindex="-1">3. 推送前测试 <a class="header-anchor" href="#_3-推送前测试" aria-label="Permalink to &quot;3. 推送前测试&quot;">​</a></h3><p>最低要求，全部执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make kernel             # 0 errors, 0 warnings (-Werror enforced)</span></span>
<span class="line"><span>make test               # host unit suite (tools/run_host_tests.py)</span></span>
<span class="line"><span>make iso                # hybrid BIOS+UEFI ISO builds</span></span>
<span class="line"><span>make reproducible-check # two clean builds -&gt; byte-identical ELF</span></span></code></pre></div><p>然后启动它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios   # or: qemu-system-x86_64 -cdrom build/opencube.iso</span></span>
<span class="line"><span>make run-uefi   # OVMF path</span></span></code></pre></div><p>如果您的修改涉及以下任何内容，还需要运行相应的深度测试：</p><table tabindex="0"><thead><tr><th>您修改了...</th><th>还需运行</th></tr></thead><tbody><tr><td>存储 / 文件系统</td><td>客户机中的 <code>fstest</code>、<code>dhtest</code></td></tr><tr><td>加密 / TLS / SSH</td><td>客户机中的 <code>cryptotest</code>、HTTPS E2E</td></tr><tr><td>看门狗 / klog / 健康</td><td><code>tools/wp12_watchdog_logging_e2e.py build/opencube.iso</code></td></tr><tr><td>完整启动路径</td><td>回归测试套件（<code>tools/run_fix4_regression.py</code>）</td></tr><tr><td>A/B 槽位或 OTA</td><td>客户机中的 <code>ab_partition_test</code>、OTA 安装测试</td></tr></tbody></table><p>CI（<code>.github/workflows/build.yml</code>）会对每个 PR 运行构建、打包、宿主测试和可复现门禁——合并前必须全部通过。</p><h3 id="_4-提交风格" tabindex="-1">4. 提交风格 <a class="header-anchor" href="#_4-提交风格" aria-label="Permalink to &quot;4. 提交风格&quot;">​</a></h3><ul><li>每个逻辑步骤一个提交；每个提交信息回答<em>做了什么</em>和<em>为什么</em>，而不仅仅是<em>做了什么</em>。</li><li>使用领域作为前缀：<code>usb: ...</code>、<code>fs: fat32: ...</code>、<code>docs: ...</code>、<code>build: ...</code>。</li><li>如果您修复了被跟踪的审计错误，请在信息中引用其编号（<code>BUG-0136</code>）。</li></ul><h3 id="_5-拉取请求" tabindex="-1">5. 拉取请求 <a class="header-anchor" href="#_5-拉取请求" aria-label="Permalink to &quot;5. 拉取请求&quot;">​</a></h3><ol><li>从 <code>main</code> 分叉或创建分支。</li><li>推送您的分支，针对 <code>cubestudio-dev/OpenCubeOS</code> 打开 PR。</li><li>填写 PR 模板中的检查清单： <ul><li>[ ] 使用 0 个警告构建（<code>-Wall -Wextra -Werror</code>）</li><li>[ ] 宿主测试通过（<code>make test</code>）</li><li>[ ] 在 QEMU 中启动（BIOS 和 UEFI）</li><li>[ ] 相关深度测试通过（上表）</li><li>[ ] 文档已更新（<code>docs/</code> 下的手册页，如果 L1 接口面有变化则更新接口列表）</li></ul></li><li>期待关于边界情况、DMA 边界和错误路径的审查意见——这对于内核代码来说是正常的。</li></ol><h2 id="报告错误" tabindex="-1">报告错误 <a class="header-anchor" href="#报告错误" aria-label="Permalink to &quot;报告错误&quot;">​</a></h2><p>通过以下方式打开问题：</p><ul><li>客户机内 <code>uname -a</code> 的构建标识符，</li><li>精确的命令序列，</li><li>串口日志（<code>-serial file:log.txt</code> 是您的朋友），</li><li>是否在 BIOS、UEFI 或两者上都能复现。</li></ul><p>安全敏感报告：见 README 中的 <code>SECURITY</code> 说明——不要公开打开问题；请通过电子邮件联系维护者。</p><h2 id="文档贡献" tabindex="-1">文档贡献 <a class="header-anchor" href="#文档贡献" aria-label="Permalink to &quot;文档贡献&quot;">​</a></h2><p><code>docs/</code> 下的文档树是产品，而不是事后考虑。如果您添加了命令或接口，相应的手册/参考页必须包含在同一 PR 中。参考页从实际树生成（<code>make api-docs</code>）——不要手动编辑生成的表格。</p><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p>通过提交贡献，您同意将其根据 Apache 2.0 许可（存储库根目录的 <code>LICENSE</code> 文件）进行许可，并且版权行可以包含项目持有者。</p><p>感谢您与我们一同构建 Open Cube OS。</p>`,32)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
